/bin/bash -lc "python - <<'PY'
import os, json
from bioblend.galaxy import GalaxyInstance
gi=GalaxyInstance(url=os.environ['GALAXY_URL'], key=open(os.environ['GALAXY_API_KEY_FILE']).read().strip())
t=gi.tools.show_tool('toolshed.g2.bx.psu.edu/repos/iuc/ncbi_datasets/datasets_download_gene/18.33.1+galaxy0', io_details=True)
def walk(inps, indent=0):
    for inp in inps:
        if isinstance(inp,dict):
            print(' '*indent, inp.get('name'), inp.get('type'), inp.get('label'), 'options', len(inp.get('options') or []))
            if 'options' in inp and inp['options']:
                print(' '*indent, 'opts:', [(o.get('value'),o.get('label')) for o in inp['options']])
            for k in ['inputs','sections']:
                if k in inp and inp[k]: walk(inp[k], indent+2)
        else: print(' '*indent, inp)
walk(t['inputs'])
PY"
